-- Run only in an isolated local database with the partner migration installed.
-- Fixtures are transactional and roll back, never send email or provision Auth accounts.
begin;
insert into motorist_organizations values('10000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000002');
insert into auth.users values('20000000-0000-4000-8000-000000000001'),('20000000-0000-4000-8000-000000000002');
insert into motorist_profiles(id,user_id,organization_id,active,role,email) values('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',true,'manager','office@example.invalid');
insert into motorist_partner_directory(id,organization_id,name,active) values('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Synthetic partner',true),('40000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Other organization',true);
insert into motorist_cases(id,organization_id,case_number,status,priority,source_type,case_type,summary) values('50000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','CONSULT-1','open','normal','partner','Konzultácia','INTERNAL SECRET');
insert into motorist_partner_memberships(id,organization_id,partner_id,auth_user_id,email,display_name,status) values('60000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','partner@example.invalid','Partner','active');
do $$ declare actor uuid:='20000000-0000-4000-8000-000000000001'; org uuid:='10000000-0000-4000-8000-000000000001'; caseid uuid:='50000000-0000-4000-8000-000000000001'; partner uuid:='40000000-0000-4000-8000-000000000001'; cmd uuid:='70000000-0000-4000-8000-000000000001'; r jsonb; r2 jsonb; p jsonb; outputid uuid:='70000000-0000-4000-8000-000000000003'; begin
 p:=jsonb_build_object('caseId',caseid,'partnerId',partner,'settlement','{"payer":"Final","reference":"CONSULT-1","agreement":"","agreementVersion":"","billable":false,"approvedCents":null,"currency":"EUR","recommendation":"Servis","serviceAccepted":false,"acceptanceEvidence":""}'::jsonb);
 r:=motorist_partner_command(actor,org,cmd,0,'set_context',p);
 r2:=motorist_partner_command(actor,org,cmd,0,'set_context',p);
 if r<>r2 then raise exception 'FAIL identical replay'; end if;
 begin perform motorist_partner_command(actor,org,cmd,0,'set_context',p||'{"different":true}'); raise exception 'FAIL content conflict allowed'; exception when serialization_failure then null; end;
 begin perform motorist_partner_command(actor,org,'70000000-0000-4000-8000-000000000008',1,'set_context',p||jsonb_build_object('partnerId','40000000-0000-4000-8000-000000000002')); raise exception 'FAIL cross-org partner allowed'; exception when insufficient_privilege then null; end;
 r:=motorist_partner_command(actor,org,'70000000-0000-4000-8000-000000000002',1,'create_assistance',jsonb_build_object('caseId',caseid,'payer','AWP','reference','AWP-1'));
 r2:=motorist_partner_command(actor,org,'70000000-0000-4000-8000-000000000002',1,'create_assistance',jsonb_build_object('caseId',caseid,'payer','AWP','reference','AWP-1'));
 if r<>r2 or (select count(*) from motorist_partner_case_links where parent_case_id=caseid)<>1 then raise exception 'FAIL assistance dedupe'; end if;
 if exists(select 1 from motorist_cases where id=(r->>'caseId')::uuid and summary='INTERNAL SECRET') then raise exception 'FAIL inherited internal data'; end if;
 if (select customer_details->>'assistanceServiceName' from motorist_cases where id=(r->>'caseId')::uuid)<>'AWP' then raise exception 'FAIL child visible payer';end if;
 perform motorist_partner_command(actor,org,'70000000-0000-4000-8000-000000000009',1,'create_assistance',jsonb_build_object('caseId',caseid,'payer','Second','reference','SECOND'));
 if (select count(*) from motorist_partner_case_links where parent_case_id=caseid)<>2 then raise exception 'FAIL new explicit intent'; end if;
 if (select settlement->>'payer' from motorist_partner_case_contexts where case_id=caseid)<>'Final' then raise exception 'FAIL independent payer'; end if;
 insert into motorist_call_sessions(id,organization_id,case_id) values('90000000-0000-4000-8000-000000000001',org,caseid),('90000000-0000-4000-8000-000000000002',org,caseid),('90000000-0000-4000-8000-000000000003',org,caseid);
 insert into motorist_operations(id,organization_id,case_id) values('91000000-0000-4000-8000-000000000001',org,caseid),('91000000-0000-4000-8000-000000000002',org,(r->>'caseId')::uuid);
 r2:=motorist_partner_report(actor,org)->0;
 if r2->>'calls'<>'3' or r2->>'consultations'<>'1' or r2->>'operations'<>'2' or r2->>'approvedCents' is not null then raise exception 'FAIL distinct report or unpriced default %',r2; end if;
 begin perform motorist_partner_command(actor,org,'70000000-0000-4000-8000-000000000031',1,'publish',jsonb_build_object('caseId',caseid,'title','Unconfirmed','result','Text','recipient','partner@example.invalid'));raise exception 'FAIL missing output confirmation';exception when raise_exception then if sqlerrm='FAIL missing output confirmation' then raise;end if;end;
 r:=motorist_partner_command(actor,org,outputid,1,'publish',jsonb_build_object('caseId',caseid,'title','Confirmed result','result','Approved partner text','recipient','partner@example.invalid','confirmed',true));
 r2:=motorist_partner_read('20000000-0000-4000-8000-000000000002',org,1,outputid);
 if jsonb_array_length(r2)<>1 or r2::text like '%INTERNAL SECRET%' or r2::text like '%AWP%' then raise exception 'FAIL reduced output'; end if;
 begin perform motorist_partner_read('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002',1,outputid);raise exception 'FAIL cross-org share allowed';exception when insufficient_privilege then null;end;
 begin perform motorist_partner_read('20000000-0000-4000-8000-000000000002',org,2,outputid);raise exception 'FAIL stale version allowed';exception when insufficient_privilege then null;end;
 r:=motorist_partner_command(actor,org,'70000000-0000-4000-8000-000000000004',1,'email_intent',jsonb_build_object('caseId',caseid,'outputId',outputid,'documentHash','abc'));
 r2:=motorist_partner_command(actor,org,'70000000-0000-4000-8000-000000000004',1,'email_intent',jsonb_build_object('caseId',caseid,'outputId',outputid,'documentHash','abc'));
 if r->>'shouldSend'<>'true' or r2->>'shouldSend'<>'false' then raise exception 'FAIL mail replay could resend'; end if;
 perform motorist_partner_command(actor,org,'70000000-0000-4000-8000-000000000005',1,'revoke_share',jsonb_build_object('caseId',caseid,'outputId',outputid));
 begin perform motorist_partner_read('20000000-0000-4000-8000-000000000002',org,1,outputid);raise exception 'FAIL revoked share allowed';exception when insufficient_privilege then null;end;
 update motorist_partner_memberships set status='disabled',membership_version=2 where id='60000000-0000-4000-8000-000000000001';
 if motorist_partner_actor('20000000-0000-4000-8000-000000000002',org,false) is not null then raise exception 'FAIL disabled actor'; end if;
 begin perform motorist_partner_read('20000000-0000-4000-8000-000000000002',org,1,null);raise exception 'FAIL old JWT after disable';exception when insufficient_privilege then null;end;
 update motorist_profiles set active=false where user_id=actor;
 begin perform motorist_partner_command(actor,org,'70000000-0000-4000-8000-000000000006',0,'set_context',p);raise exception 'FAIL disabled office';exception when insufficient_privilege then null;end;
 if has_table_privilege('authenticated','motorist_partner_outputs','SELECT') or has_function_privilege('authenticated','motorist_partner_read(uuid,uuid,bigint,uuid)','EXECUTE') then raise exception 'FAIL public grants'; end if;
 raise notice 'PASS partner command dedupe, independent payer, explicit child intent, reduced snapshots, share/version/org revocation, mail replay and grants';
end $$;
rollback;

begin;
insert into motorist_organizations values('10000000-0000-4000-8000-000000000001');
insert into auth.users values('20000000-0000-4000-8000-000000000001'),('20000000-0000-4000-8000-000000000002');
insert into motorist_profiles(id,user_id,organization_id,active,role,email) values('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',true,'manager','office@example.invalid');
insert into motorist_partner_directory(id,organization_id,name,active) values('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Synthetic partner',true);
insert into motorist_towing_memberships(id,organization_id,auth_user_id,active,email) values('80000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002',true,'field@example.invalid');
do $$ declare actor uuid:='20000000-0000-4000-8000-000000000001'; org uuid:='10000000-0000-4000-8000-000000000001'; fielduser uuid:='20000000-0000-4000-8000-000000000002'; member uuid:='60000000-0000-4000-8000-000000000001'; invite uuid:='70000000-0000-4000-8000-000000000010'; p jsonb; r jsonb; begin
 p:=jsonb_build_object('commandId',invite,'membershipId',member,'partnerId','40000000-0000-4000-8000-000000000001','userId',fielduser,'existing',true,'email','field@example.invalid','displayName','Field and partner','payloadHash','hash');
 perform motorist_partner_membership_command(actor,org,'prepare',p);
 perform motorist_partner_membership_command(actor,org,'prepare',p);
 begin perform motorist_partner_membership_command(actor,org,'prepare',p||'{"payloadHash":"changed"}');raise exception 'FAIL invite content changed';exception when serialization_failure then null;end;
 perform motorist_partner_membership_command(actor,org,'commit',jsonb_build_object('commandId',invite,'membershipId',member));
 if motorist_partner_actor(fielduser,org,false) is not null or motorist_partner_actor(fielduser,org,true) is null then raise exception 'FAIL invited user resource gate';end if;
 begin perform motorist_partner_accept(fielduser,org,1,'70000000-0000-4000-8000-000000000099');raise exception 'FAIL wrong generation';exception when insufficient_privilege then null;end;
 update motorist_partner_invitation_intents set expires_at=now()-interval '1 second' where id=invite;
 begin perform motorist_partner_accept(fielduser,org,1,invite);raise exception 'FAIL expired invite';exception when insufficient_privilege then null;end;
 update motorist_partner_invitation_intents set expires_at=now()+interval '1 day' where id=invite;
 perform motorist_partner_accept(fielduser,org,1,invite);
 if motorist_partner_actor(fielduser,org,false) is null then raise exception 'FAIL accepted user';end if;
 if exists(select 1 from motorist_profiles where user_id=fielduser) then raise exception 'FAIL fake dispatch profile';end if;
 perform motorist_partner_membership_command(actor,org,'disable',jsonb_build_object('membershipId',member,'commandId','70000000-0000-4000-8000-000000000015','expectedVersion',1));
 if motorist_partner_actor(fielduser,org,true) is not null then raise exception 'FAIL revoked invitation';end if;
 if not exists(select 1 from motorist_towing_memberships where auth_user_id=fielduser and active) then raise exception 'FAIL field membership affected';end if;
 raise notice 'PASS existing field account + partner, invitation idempotency, generation, expiry, password completion, revoke without fake profile';
end $$;
rollback;
